#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <string.h>
#include <stdio.h>
#include <cbprintf.h>

#define TEST_BUFFER_SIZE 128

static char test_buf[TEST_BUFFER_SIZE];

static int cbprintf_out(int c, void *ctx)
{
    struct cbprintf_buf *buf = (struct cbprintf_buf *)ctx;

    if (buf->offset < buf->size - 1) {
        buf->buf[buf->offset++] = (char)c;
        buf->buf[buf->offset] = '\0';
        return 0;
    }

    return -ENOSPC;
}

static void unpack(const char *fmt, const char *compare_buf, const u8_t *package_buf,
		   size_t package_len)
{
	struct cbprintf_buf buf = {
		.buf = test_buf,
		.size = sizeof(test_buf),
		.offset = 0,
	};
	struct cbprintf_config cfg = {
		.cb = cbprintf_out,
		.ctx = &buf,
	};

	printk("runtime package 0x%x:\n", (uintptr_t)package_buf);
	for (size_t i = 0; i < package_len; i++) {
		printk("%02x ", package_buf[i]);
	}
	printk("\n");

	int ret = cbprintf_package_ptr_unpack(fmt, package_buf, package_len, &cfg);
	zassert_equal(ret, 0, "Unpack failed");
	zassert_equal(strcmp(buf.buf, compare_buf), 0, "Unpacked string mismatch");
}

static void test_cbprintf_fsc_package(void)
{
	const char *fmt = "test %s %d %x";
	const char *s = "string";
	int d = 123;
	int x = 0xABC;
	const char *compare_buf = "test string 123 abc";

	CBPRINTF_PACKAGE_PTR_DECLARE(package_ptr);

	cbprintf_package_ptr_get(package_ptr, fmt, s, d, x);

	unpack(fmt, compare_buf, package_ptr->buf, package_ptr->len);
}

static void test_cbprintf_must_runtime_package(void)
{
	const char *fmt = "test %s %d %x";
	const char *s = "string";
	int d = 123;
	int x = 0xABC;
	const char *compare_buf = "test string 123 abc";

	CBPRINTF_MUST_RUNTIME_PACKAGE_DECLARE(package_buf, 64);

	cbprintf_must_runtime_package_get(package_buf, sizeof(package_buf), fmt, s, d, x);

	unpack(fmt, compare_buf, package_buf.buf, package_buf.len);
}

static void test_cbprintf_package(void)
{
	const char *fmt = "test %s %d %x";
	const char *s = "string";
	int d = 123;
	int x = 0xABC;
	const char *compare_buf = "test string 123 abc";

	CBPRINTF_PACKAGE_DECLARE(package_buf, 64);

	cbprintf_package_get(package_buf, sizeof(package_buf), fmt, s, d, x);

	unpack(fmt, compare_buf, package_buf.buf, package_buf.len);
}

ZTEST_SUITE(cbprintf_package, NULL, NULL, NULL, NULL, NULL);

ZTEST_TEST(cbprintf_package, test_cbprintf_fsc_package)
{
	test_cbprintf_fsc_package();
}

ZTEST_TEST(cbprintf_package, test_cbprintf_must_runtime_package)
{
	test_cbprintf_must_runtime_package();
}

ZTEST_TEST(cbprintf_package, test_cbprintf_package)
{
	test_cbprintf_package();
}
